-- HABAŞ PLATE MILL — 20.07.2026 tarihli öncelikli 5 vinç teklifi.
--
-- Kaynak çalışma kitabı V13'tür. Kullanıcının kapsam kararı gereği yalnız
-- 101-A, 101-B, 102, 201 ve 202 aktarılır; diğer 14 vinç bu kayda girmez.
-- Müşteri teklifindeki net toplam 2.229.200 EUR'dur. Ana kiriş ve platformun
-- 810.800 EUR satış bedeli HABAŞ kapsamı olarak anahtar teslim fiyattan düşer.
--
-- Maliyet satırları Excel MALİYET DETAYI 4–8'den gelir. Çelik maliyetinin
-- kaynak sayfada bütün vinç ağırlığı üzerinden tek sütunda hesaplanması,
-- kapsam değişikliğini görünmez kılıyordu. V13'te verilen ana kiriş+platform
-- ağırlıkları (49.800 / 28.200 kg) ve aynı birim fiyatlar kullanılarak bu dört
-- satır ORION/HABAŞ paylarına ayrılır; HABAŞ payı verisi korunarak toplam dışı
-- kalır. 19 vinçlik proje geneli/oranlar beşli pakete varsayımla dağıtılmaz.

do $$
declare
  v_creator uuid;
  v_customer uuid;
  v_offer uuid;
begin
  select p.id into v_creator
  from public.profiles p
  where p.email = 'scolakoglu@orioncranes.com'
  limit 1;

  if v_creator is null then
    select p.id into v_creator
    from public.profiles p
    where p.role::text = 'admin'
    order by p.created_at
    limit 1;
  end if;
  if v_creator is null then
    raise exception 'HABAŞ teklifini aktaracak yönetici profili bulunamadı';
  end if;

  select c.id into v_customer
  from public.customers c
  where btrim(c.short_name) = 'HABAŞ' or btrim(c.name) = 'HABAŞ'
  order by (btrim(c.short_name) = 'HABAŞ') desc, c.created_at
  limit 1;
  if v_customer is null then
    raise exception 'HABAŞ müşteri kaydı bulunamadı';
  end if;

  select o.id into v_offer
  from public.offers o
  where o.offer_no = 'TETR-20260720-1';

  if v_offer is not null and not exists (
    select 1 from public.offers o
    where o.id = v_offer
      and o.customer_id = v_customer
      and o.subject = 'PLATE MILL TESİSİ ÖNCELİKLİ 5 ADET TAVAN VİNCİ'
  ) then
    raise exception 'TETR-20260720-1 başka bir teklife ait';
  end if;

  if v_offer is null then
    insert into public.offers (
      offer_no, lang, issue_date, seq, issued_on, customer_id, customer_name,
      subject, status, currency, created_by, created_at, updated_at
    ) values (
      'TETR-20260720-1', 'tr', date '2026-07-20', 1, date '2026-07-20', v_customer,
      'HABAŞ SINAİ VE TIBBİ GAZLAR İST. END. A.Ş.',
      'PLATE MILL TESİSİ ÖNCELİKLİ 5 ADET TAVAN VİNCİ',
      'sent', 'EUR', v_creator,
      timestamptz '2026-07-20 00:00:00+03', timestamptz '2026-07-20 00:00:00+03'
    ) returning id into v_offer;
  end if;

  insert into public.offer_revisions (
    offer_id, rev_no, label, status, payload, notes, created_by,
    created_at, updated_at, issued_at, issued_by
  ) values (
    v_offer, 0, '', 'issued',
